1	import Foundation
2	
3	/// Streams daemon log lines from `ws://…/logs/ws/daemon`.
4	///
5	/// The daemon tails `journalctl -u reachy-mini-daemon` — plain text lines
6	/// (short-iso). The router is mounted at the app ROOT (not under `/api`) and
7	/// only with `--wireless-version`: real robot only, the simulator rejects the
8	/// upgrade with HTTP 403 (verified against daemon main.py and a live sim).
9	/// Same reconnect-with-backoff shape as `StateStreamClient`.
10	public struct LogStreamClient: Sendable {
11	    public static let path = "/logs/ws/daemon"
12	
13	    private let url: URL
14	    private let session: URLSession
15	
16	    public init(address: RobotAddress, session: URLSession = .shared) throws {
17	        guard let url = address.webSocketURL(path: Self.path) else {
18	            throw ReachyKitError.invalidAddress(address)
19	        }
20	        self.url = url
21	        self.session = session
22	    }
23	
24	    /// Log lines; never throws, ends only on cancellation. Reconnects with backoff.
25	    public func lines() -> AsyncStream<String> {
26	        let (stream, continuation) = AsyncStream.makeStream(
27	            of: String.self,
28	            bufferingPolicy: .bufferingNewest(500)
29	        )
30	        let task = Task { [url, session] in
31	            var backoff = Duration.milliseconds(500)
32	            while !Task.isCancelled {
33	                let socket = session.webSocketTask(with: url)
34	                socket.resume()
35	                do {
36	                    while true {
37	                        let message = try await socket.receive()
38	                        if case let .string(text) = message {
39	                            continuation.yield(text)
40	                            backoff = .milliseconds(500)
41	                        }
42	                    }
43	                } catch {
44	                    socket.cancel(with: .goingAway, reason: nil)
45	                }
46	                if Task.isCancelled {
47	                    break
48	                }
49	                try? await Task.sleep(for: backoff)
50	                backoff = min(backoff * 2, .seconds(15))
51	            }
52	            continuation.finish()
53	        }
54	        continuation.onTermination = { _ in task.cancel() }
55	        return stream
56	    }
57	}
