import CoreTransferable
import Foundation
import Observation
import SwiftUI
import UniformTypeIdentifiers

enum LogLevel: Int, CaseIterable, Sendable, Comparable {
    case debug, info, warning, error

    static func < (lhs: Self, rhs: Self) -> Bool { lhs.rawValue < rhs.rawValue }
}

struct LogEntry: Identifiable, Sendable, Equatable {
    let id: Int
    let timestamp: String?
    let message: String
    let level: LogLevel
    let text: String

    init(id: Int, raw: String) {
        self.id = id
        text = raw
        let parts = raw.split(separator: " ", maxSplits: 1, omittingEmptySubsequences: false)
        if let first = parts.first, Self.isTimestamp(first), parts.count == 2 {
            timestamp = String(first)
            message = String(parts[1])
        } else {
            timestamp = nil
            message = raw
        }
        level = Self.level(of: message)
    }

    private static func isTimestamp(_ token: Substring) -> Bool {
        token.count >= 19 && token.dropFirst(10).first == "T" && token.prefix(4).allSatisfy(\.isNumber)
    }

    private static func level(of message: String) -> LogLevel {
        if message.contains("ERROR") || message.contains("CRITICAL") || message.contains("FATAL")
            || message.contains("Traceback")
        {
            return .error
        }
        if message.contains("WARN") {
            return .warning
        }
        if message.contains("DEBUG") {
            return .debug
        }
        return .info
    }
}

@MainActor
@Observable
final class LogConsoleModel {
    static let capacities = [1000, 5000, 20000]

    private(set) var entries: [LogEntry] = []
    private(set) var visible: [LogEntry] = []
    private(set) var pending: [LogEntry] = []

    var paused = false {
        didSet {
            if !paused { flush() }
        }
    }

    var query = "" {
        didSet { recompute() }
    }

    var minimumLevel = LogLevel.debug {
        didSet { recompute() }
    }

    var capacity = 5000 {
        didSet {
            trim()
            recompute()
        }
    }

    private var nextID = 0

    func ingest(_ chunk: String) {
        var appended: [LogEntry] = []
        for raw in chunk.split(separator: "\n", omittingEmptySubsequences: true) {
            appended.append(LogEntry(id: nextID, raw: String(raw)))
            nextID += 1
        }
        guard !appended.isEmpty else { return }
        if paused {
            pending.append(contentsOf: appended)
            return
        }
        entries.append(contentsOf: appended)
        trim()
        visible.append(contentsOf: appended.filter(matches))
        trimVisible()
    }

    func clear() {
        entries = []
        visible = []
        pending = []
    }

    var isFiltered: Bool {
        !query.isEmpty || minimumLevel != .debug
    }

    func exportText(address: String, exportedAt: Date) -> String {
        var header = """
        # Reachy Mini daemon log
        # robot: \(address)
        # exported: \(exportedAt.formatted(.iso8601))
        # lines: \(visible.count) of \(entries.count)
        """
        if isFiltered {
            header += " (level: \(minimumLevel), search: \"\(query)\")"
        }
        return header + "\n" + visible.map(\.text).joined(separator: "\n") + "\n"
    }

    private func flush() {
        guard !pending.isEmpty else { return }
        entries.append(contentsOf: pending)
        visible.append(contentsOf: pending.filter(matches))
        pending = []
        trim()
        trimVisible()
    }

    private func matches(_ entry: LogEntry) -> Bool {
        entry.level >= minimumLevel
            && (query.isEmpty || entry.text.localizedCaseInsensitiveContains(query))
    }

    private func trim() {
        if entries.count > capacity {
            entries.removeFirst(entries.count - capacity)
        }
    }

    private func trimVisible() {
        guard let oldest = entries.first?.id else {
            visible = []
            return
        }
        if let drop = visible.firstIndex(where: { $0.id >= oldest }), drop > 0 {
            visible.removeFirst(drop)
        }
    }

    private func recompute() {
        visible = entries.filter(matches)
    }
}

struct LogExport: Transferable, Sendable {
    let entries: [LogEntry]
    let header: String
    let host: String

    static var transferRepresentation: some TransferRepresentation {
        DataRepresentation(exportedContentType: .plainText) { export in
            Data(export.text.utf8)
        }
        .suggestedFileName { export in export.filename }
    }

    var text: String {
        header + "\n" + entries.map(\.text).joined(separator: "\n") + "\n"
    }

    var filename: String {
        let stamp = Date().formatted(
            .verbatim("\(year: .defaultDigits)\(month: .twoDigits)\(day: .twoDigits)-\(hour: .twoDigits(clock: .twentyFourHour, hourCycle: .zeroBased))\(minute: .twoDigits)\(second: .twoDigits)",
                      timeZone: .current, calendar: .current)
        )
        return "reachy-daemon-\(host)-\(stamp).txt"
    }
}

enum Clipboard {
    static func copy(_ text: String) {
        #if os(iOS)
            UIPasteboard.general.string = text
        #else
            NSPasteboard.general.clearContents()
            NSPasteboard.general.setString(text, forType: .string)
        #endif
    }
}

