import Foundation
@testable import ReachyUI
import Testing

@MainActor
@Suite("LogExport")
struct LogExportTests {
    private let epoch = Date(timeIntervalSince1970: 0)

    @Test("copy text is the visible log without a header")
    func copyText() {
        let model = LogConsoleModel()
        model.ingest("boot ok\nERROR boom")
        model.minimumLevel = .error

        #expect(model.copyText == "ERROR boom")
    }

    @Test("export text opens with a header and carries every visible line")
    func exportText() {
        let model = LogConsoleModel()
        model.ingest("boot ok\nERROR boom")

        let text = model.export(address: "10.42.0.1:8000").text(exportedAt: epoch)

        #expect(text.hasPrefix("# Reachy Mini daemon log\n# robot: 10.42.0.1:8000\n"))
        #expect(text.contains("# exported: 1970-01-01T00:00:00Z"))
        #expect(text.contains("# lines: 2 of 2\n"))
        #expect(text.contains("boot ok"))
        #expect(text.hasSuffix("ERROR boom\n"))
    }

    @Test("header records the filter that truncated the export")
    func filteredHeader() {
        let model = LogConsoleModel()
        model.ingest("boot ok\nERROR boom")
        model.minimumLevel = .error

        let text = model.export(address: "reachy-mini.local").text(exportedAt: epoch)

        #expect(text.contains("# lines: 1 of 2 (level: error)"))
        #expect(!text.contains("boot ok"))
    }

    @Test("file name carries the host and a sortable UTC stamp")
    func filename() {
        let export = LogExport(entries: [], address: "10.42.0.1:8000", totalCount: 0, filterSummary: nil)

        #expect(export.filename(exportedAt: epoch) == "reachy-daemon-10.42.0.1-8000-19700101T000000.txt")
    }
}

import CoreTransferable
import Foundation
import UniformTypeIdentifiers

/// Share payload for the visible log. Holds a snapshot array — cheap to rebuild on every
/// toolbar render — and serializes only when the user actually shares.
struct LogExport: Transferable, Sendable {
    let entries: [LogEntry]
    let address: String
    let totalCount: Int
    let filterSummary: String?

    /// UTC so exports from different machines sort together.
    private static let stamp: Date.ISO8601FormatStyle = .iso8601
        .year().month().day()
        .dateSeparator(.omitted)
        .dateTimeSeparator(.standard)
        .time(includingFractionalSeconds: false)
        .timeSeparator(.omitted)

    static var transferRepresentation: some TransferRepresentation {
        DataRepresentation(exportedContentType: .plainText) { export in
            Data(export.text(exportedAt: .now).utf8)
        }
        .suggestedFileName { $0.filename(exportedAt: .now) }
    }

    /// An exported log is read detached from the app, so it has to say what was captured
    /// and whether a filter truncated it.
    func text(exportedAt: Date) -> String {
        var header = """
        # Reachy Mini daemon log
        # robot: \(address)
        # exported: \(exportedAt.formatted(.iso8601))
        # lines: \(entries.count) of \(totalCount)
        """
        if let filterSummary {
            header += " (\(filterSummary))"
        }
        return header + "\n" + entries.map(\.text).joined(separator: "\n") + "\n"
    }

    func filename(exportedAt: Date) -> String {
        let host = address.replacingOccurrences(of: ":", with: "-")
        return "reachy-daemon-\(host)-\(exportedAt.formatted(Self.stamp)).txt"
    }
}

